package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EntityListeners;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.history.HistoryListener;

/** A sheet's rate for a grade: a percent with two decimals (0.00 or more), in force from its
 *  from-date (null: from the beginning of time) through its to-date (null: with no end). */
@Entity
@Table(name = "rate")
@EntityListeners(HistoryListener.class)
public class Rate {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "rate", nullable = false, precision = 7, scale = 2)
    private BigDecimal rate;

    @Column(name = "from_date")
    private LocalDate from;

    @Column(name = "to_date")
    private LocalDate to;

    @Column(name = "version", nullable = false)
    private int version = 1;

    protected Rate() {
    }

    public Rate(String sheetId, String grade, LocalDate from, LocalDate to, BigDecimal rate) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.from = from;
        this.to = to;
        this.rate = rate;
    }

    /** A rate as it stood with a given version count, read back from the sheet's history. */
    public Rate(String sheetId, String grade, LocalDate from, LocalDate to, BigDecimal rate, int version) {
        this(sheetId, grade, from, to, rate);
        this.version = version;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    public LocalDate getFrom() {
        return from;
    }

    /** The last date the rate applies on; null when it has no end. */
    public LocalDate getTo() {
        return to;
    }

    /** Whether the rate has ended by a date: it has a to-date before the date. */
    public boolean endedBy(LocalDate date) {
        return to != null && to.isBefore(date);
    }

    /** Whether the rate is in force on a date: its from-date is none or on or before the date. */
    public boolean appliesOn(LocalDate date) {
        return from == null || !from.isAfter(date);
    }

    public BigDecimal getRate() {
        return rate;
    }

    /** How many versions the rate has: 1 for one never replaced; the value in force is the newest. */
    public int getVersion() {
        return version;
    }

    /** Make a new value and to-date the newest version, the one in force. */
    public void newVersion(BigDecimal rate, LocalDate to) {
        this.rate = rate;
        this.to = to;
        this.version++;
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Optional;
import java.util.stream.Stream;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.history.History;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The rates set on a sheet for each grade, each in force from its from-date. A grade with no rate
 *  in force on a date on a sheet takes its parent sheet's, then the parent's parent's, up to
 *  {@link #PARENT_LEVELS} levels up. */
@Service
public class RateService {

    /** How many levels of parent sheets are looked to for a rate the sheet has none in force for. */
    public static final int PARENT_LEVELS = 3;

    private final RateRepository rates;
    private final RateVersionRepository versions;
    private final SheetService sheets;
    private final SheetRepository sheetRepository;
    private final History history;
    private final Audit audit;

    public RateService(RateRepository rates, RateVersionRepository versions, SheetService sheets, SheetRepository sheetRepository, History history,
            Audit audit) {
        this.rates = rates;
        this.versions = versions;
        this.sheets = sheets;
        this.sheetRepository = sheetRepository;
        this.history = history;
        this.audit = audit;
    }

    /** The sheet's parent sheet's id; null when it has none. The parent is not kept in the sheet's
     *  history: a sheet shown as of a past day falls back to its parent as it stands now. */
    private String parentOf(String sheetId) {
        return sheetRepository.findById(sheetId).map(Sheet::getParentId).orElse(null);
    }

    /** The sheets the sheet's rates fall back to, nearest first: its parent, the parent's parent, up
     *  to {@link #PARENT_LEVELS} levels up. */
    public List<String> ancestors(String sheetId) {
        List<String> found = new ArrayList<>();
        String sheet = parentOf(sheetId);
        while (sheet != null && found.size() < PARENT_LEVELS && !sheet.equals(sheetId) && !found.contains(sheet)) {
            found.add(sheet);
            sheet = parentOf(sheet);
        }
        return found;
    }

    /** The sheet's rates by grade, each grade's from the earliest. */
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromAscIdAsc(sheetId);
    }

    /** The sheet's rates by grade, each grade's from the earliest, as they stood at the end of a day
     *  (null: as they stand now). */
    public List<Rate> list(String sheetId, LocalDate asOf) {
        if (asOf == null) {
            return list(sheetId);
        }
        return Stream.of("A", "B", "C")
                .flatMap(grade -> history.rates(sheetId, grade, asOf).stream()
                        .sorted(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder()))))
                .toList();
    }

    /** The grade's rate in force on a date: the one whose from-date is the latest on or before it
     *  (a rate with no from-date applies from the beginning of time); none applies when there is no
     *  such rate, or when that one's to-date is before the date. When none applies on the sheet, the
     *  parent sheet's is taken, then the parent's parent's, up to {@link #PARENT_LEVELS} levels up;
     *  empty when none applies on any of them. */
    public Optional<Rate> rateOn(String sheetId, String grade, LocalDate date) {
        return rateOn(sheetId, grade, date, null);
    }

    /** The grade's rate in force on a date as the rates (the sheet's and its parent sheets') stood
     *  at the end of a day (null: as they stand now). */
    public Optional<Rate> rateOn(String sheetId, String grade, LocalDate date, LocalDate asOf) {
        Optional<Rate> own = ownRateOn(sheetId, grade, date, asOf);
        if (own.isPresent()) {
            return own;
        }
        for (String ancestor : ancestors(sheetId)) {
            Optional<Rate> theirs = ownRateOn(ancestor, grade, date, asOf);
            if (theirs.isPresent()) {
                return theirs;
            }
        }
        return Optional.empty();
    }

    private Optional<Rate> ownRateOn(String sheetId, String grade, LocalDate date, LocalDate asOf) {
        return inForce(asOf == null ? rates.findBySheetIdAndGradeOrderByFromAsc(sheetId, grade)
                : history.rates(sheetId, grade, asOf), date);
    }

    private static Optional<Rate> inForce(List<Rate> theirs, LocalDate date) {
        return theirs.stream()
                .filter(rate -> rate.appliesOn(date))
                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .filter(rate -> !rate.endedBy(date));
    }

    /** Set the rate for a grade from a date (null: from the beginning of time) through a date (null:
     *  with no end). When the grade has a rate from that date, the value it held is kept as an older
     *  version and the new one becomes its newest version, the one in force. A to-date before the from-date
     *  is refused. */
    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal rate) {
        if (from != null && to != null && to.isBefore(from)) {
            throw new RateRefusedException("A rate's to-date cannot be before its from-date.");
        }
        sheets.load(sheetId);
        BigDecimal scaled = rate.setScale(2, RoundingMode.UNNECESSARY);
        Optional<Rate> had = from == null
                ? rates.findBySheetIdAndGradeAndFromIsNull(sheetId, grade)
                : rates.findBySheetIdAndGradeAndFrom(sheetId, grade, from);
        Rate saved = had
                .map(existing -> {
                    versions.save(new RateVersion(existing, sheets.today(sheetId), user));
                    existing.newVersion(scaled, to);
                    return existing;
                })
                .orElseGet(() -> new Rate(sheetId, grade, from, to, scaled));
        saved = rates.saveAndFlush(saved);
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade
                + " rate=" + saved.getRate().toPlainString() + (from != null ? " from=" + from : "")
                + (to != null ? " to=" + to : ""));
        return saved;
    }
}
-- A rate is kept as versions: setting a rate for a grade and from-date that already has one keeps
-- the value it replaces as an older version and makes the new one the next version, the one in
-- force. version is the rate's version count (1 for a rate never replaced).
ALTER TABLE rate ADD COLUMN version INT NOT NULL DEFAULT 1;
ALTER TABLE rate_history ADD COLUMN version INT NOT NULL DEFAULT 1;

-- Each older version of a rate: the value and to-date it held as that version, and the sheet's
-- today and the user when it was replaced.
CREATE TABLE rate_version (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    rate_id BIGINT NOT NULL REFERENCES rate (id),
    version INT NOT NULL,
    rate DECIMAL(7, 2) NOT NULL,
    to_date DATE,
    replaced_on DATE,
    replaced_by VARCHAR(200) NOT NULL
);
CREATE UNIQUE INDEX rate_version_rate ON rate_version (rate_id, version);
-- A rate can carry a from-date: a grade may have several rates, and a claim uses the one whose
-- from-date is the latest on or before the claim's date. A rate with no from-date applies from the
-- beginning of time. A grade has at most one rate per from-date (no from-date counting as one).
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
DROP INDEX rate_sheet_grade;
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet_id, grade, from_key);
-- A rate can carry a to-date: it applies through that date. A claim dated after the to-date of the
-- rate that would apply to it (the latest from-date on or before the claim's date) has no rate.
ALTER TABLE rate ADD COLUMN to_date DATE;
